package africa.growtogether.platform.eip;
import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.*; import javax.crypto.*; import javax.crypto.spec.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class IntegrationCredentialCrypto {private final SecretKey key; private final SecureRandom random=new SecureRandom(); private final String keyId;
 public IntegrationCredentialCrypto(@Value("${gt.eip.encryption-key:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=}") String encoded,@Value("${gt.eip.encryption-key-id:eip-development-key}") String keyId){byte[] raw=Base64.getDecoder().decode(encoded);if(raw.length!=32)throw new IllegalStateException("GT EIP encryption key must be 32 bytes");key=new SecretKeySpec(raw,"AES");this.keyId=keyId;}
 public String encrypt(String plaintext){if(plaintext==null||plaintext.isBlank())return null;try{byte[] iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[] out=c.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));byte[] all=new byte[iv.length+out.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(out,0,all,iv.length,out.length);return Base64.getUrlEncoder().withoutPadding().encodeToString(all);}catch(Exception e){throw new IllegalStateException("Unable to encrypt integration credential",e);}}
 public String keyId(){return keyId;}}
